export function rentalQuote(startDate, endDate, pricePerDay, today) {
  const s = typeof startDate === 'string' ? startDate.trim() : ''
  const e = typeof endDate === 'string' ? endDate.trim() : ''

  if (!s || !e) {
    return { days: 0, total: 0, error: null }
  }

  if (s < today) {
    return { days: 0, total: 0, error: 'Start date cannot be in the past.' }
  }

  if (e < s) {
    return { days: 0, total: 0, error: 'End date must be after start date.' }
  }

  const start = parseDate(s)
  const end = parseDate(e)

  if (start === null || end === null) {
    return { days: 0, total: 0, error: 'Invalid date.' }
  }

  const days = Math.round((end - start) / 86400000) + 1

  return { days, total: days * pricePerDay, error: null }
}

function parseDate(str) {
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(str)
  if (!m) return null
  const year = +m[1]
  const month = +m[2]
  const day = +m[3]
  const time = Date.UTC(year, month - 1, day)
  const d = new Date(time)
  if (d.getUTCFullYear() !== year || d.getUTCMonth() !== month - 1 || d.getUTCDate() !== day) {
    return null
  }
  return time
}
